#!/usr/bin/env bash\nset -euo pipefail\n\n# ------------------------------------------------------------\n# nightly-disk-usage-visualizer\n# ------------------------------------------------------------\n# Usage: ./src/main.sh [target_dir] [max_depth]\n#   target_dir – directory to scan (default: current directory)\n#   max_depth  – how many levels of sub‑directories to include (default: 2)\n#\n# The script gathers sizes using the command defined in DU_CMD (defaults\n# to "du -sk").  This indirection allows the test suite to replace\n# the command with a deterministic mock.\n# ------------------------------------------------------------\n\nTARGET="${1:-.}"\nDEPTH="${2:-2}"\nDU_CMD="${DU_CMD:-du -sk}"\n\n# Ensure the target exists\nif [[ ! -d "$TARGET" ]]; then\n  echo "Error: target directory '$TARGET' does not exist" >&2\n  exit 1\nfi\n\n# Collect sizes for each sub‑directory up to the requested depth\ndeclare -A sizes\nwhile IFS=$'\t' read -r size dir; do\n  sizes["$dir"]=$size\n# shellcheck disable=SC2034\ndone < <(find "$TARGET" -mindepth 1 -maxdepth "$DEPTH" -type d -exec $DU_CMD "{}" + | sort -nr)\n\n# Determine the maximum size to scale the bar chart\nmax=0\nfor s in "${sizes[@]}"; do\n  (( s > max )) && max=$s\n done\n# Avoid division‑by‑zero\n(( max == 0 )) && max=1\n\n# Print the report – sorted by size descending\nfor dir in "${!sizes[@]}"; do\n  size=${sizes[$dir]}\n  # Scale bar length to a maximum of 40 characters\n  bar_len=$(( size * 40 / max ))\n  # Build the bar string\n  bar=$(printf "%0.s#" $(seq 1 $bar_len))\n  printf "%-30s %6sK %s\n" "$(basename "$dir")" "$size" "$bar"\n done | sort -k2 -n -r\n
